flex;justify-content:space-between;gap:20px;padding:22px 54px;background:#f6f8f8;border-top:1px solid var(--line);font-size:11px;color:var(--muted)}.preview-banner{max-width:1160px;margin:24px auto -16px;padding:12px 20px;background:var(--amber-light);border:1px solid #e8d8b6;border-radius:10px;font-size:12px;color:#774d18}.fine-print{font-size:11px;color:var(--muted);margin-top:12px}
