if (!query || typeof query !== 'object' || Array.isArray(query)) throw new Error('Expected named tool inputs, not a query string.');
const fields = ["product","bucket","group_by"];
const params = Object.fromEntries(fields.filter(key => Object.prototype.hasOwnProperty.call(query, key)).map(key => [key, query[key]]));
return JSON.stringify(workshopTool("get_movement", rows, params).map(item => item.json), null, 2);

parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "product": {
      "type": "string",
      "description": "Protection, Savings or Funeral. Empty for whole book.",
      "default": ""
    },
    "bucket": {
      "type": "string",
      "description": "One of: expected_change, claims_variance, lapse_variance, expense_variance, basis_change, new_business. Empty for headline.",
