      "default": ""
    },
    "group_by2": {
      "type": "string",
      "description": "A second dimension to cross-tabulate against group_by. Leave blank for one dimension.",
      "default": ""
    },
    "status": {
      "type": "string",
      "description": "in_force, lapsed or claimed. Leave blank for all.",
      "default": ""
    },
    "new_business_only": {
      "type": "string",
      "description": "true for policies written in the period, otherwise leave blank.",
      "default": ""
    }
  },
  "required": [],
  "additionalProperties": true
}

