}
let prompt;
if (revision === 0) {
  prompt = 'INITIAL INVESTIGATION\nORIGINAL QUESTION\n' + original;
} else {
  const review = item.json.output;
  if (!review || typeof review !== 'object' || Array.isArray(review) ||
      review.ready_for_reporting !== false ||
      typeof review.context !== 'string' || !review.context.trim()) {
    throw new Error('Invalid HAF revision handoff. Expected output.ready_for_reporting=false and a non-empty output.context. Inspect the preceding HAF result; no Investigator call was made.');
  }
  if (revision >= 3) {
    throw new Error('HAF REVIEW UNRESOLVED: The initial investigation and two revisions are complete. No approved report was generated. Open the latest HAF Agent output and read CORRECTIONS REQUESTED for the remaining blockers.');
  }
  prompt = 'REVISION ' + revision + ' OF 2\nORIGINAL QUESTION\n' + original +
    '\n\nCURRENT HAF REQUIREMENTS AND CORRECTIONS\n' + review.context;
}
return [{json: {investigation_prompt: prompt, revision_number: revision}, pairedItem: {item: 0}}];
